const fs=require('fs'),p=require('path'),c=require('crypto');
const need=(v,m)=>{if(!v)throw Error(m)},fields=['dev','ino','mode','size','mtimeNs','ctimeNs','nlink'];
function readExact(i){const x=i.path;need(p.isAbsolute(x)&&p.normalize(x)===x,'absolute normalized');let a='/';for(const k of x.split('/').filter(Boolean)){a=p.join(a,k);need(!fs.lstatSync(a).isSymbolicLink(),'symlink');}const s=fs.lstatSync(x,{bigint:true});need(s.isFile()&&s.size<=67108864n,'regular cap');if(i.bytes!==undefined)need(s.size===BigInt(i.bytes),'initial size');const same=t=>fields.every(k=>t[k]===s[k]);const fd=fs.openSync(x,fs.constants.O_RDONLY|fs.constants.O_NOFOLLOW);let b;try{need(same(fs.fstatSync(fd,{bigint:true})),'fd-before');const chunks=[];let n=0,cap=Number(s.size)+1;while(n<cap){const z=Buffer.alloc(Math.min(65536,cap-n)),g=fs.readSync(fd,z,0,z.length,null);if(!g)break;chunks.push(z.subarray(0,g));n+=g;}b=Buffer.concat(chunks);need(b.length===Number(s.size)&&same(fs.fstatSync(fd,{bigint:true})),'fd-after/length');}finally{fs.closeSync(fd);}need(same(fs.lstatSync(x,{bigint:true}))&&fs.realpathSync(x)===x,'path-after');const r={path:x,bytes:b.length,sha256:c.createHash('sha256').update(b).digest('hex')};if(i.sha256!==undefined)need(r.sha256===i.sha256,'hash');return {...r,body:b};}
const simple=r=>({path:r.path,bytes:r.bytes,sha256:r.sha256});

const mode=process.argv[1]||'preseal';
need(mode==='preseal'||mode==='final6','mode');
const dir="/Volumes/AI_DATA/development/det-review-evidence/ri243-native-hook-acquisition-_9p7ia0h";
const expect4=['HOOK_ROLE_MAP.md','HOOK_ACQUISITION_CONTRACT.md','HANDOFF.md','SOURCE_REFERENCES.json'].sort();
const expect6=[...expect4,'AUTHOR_VERIFICATION.json','HANDOFF.json'].sort();
need(fs.lstatSync(dir).isDirectory()&&!fs.lstatSync(dir).isSymbolicLink(),'reservation');
need(JSON.stringify(fs.readdirSync(dir).sort())===JSON.stringify(mode==='preseal'?expect4:expect6),'namespace');
const reads=new Map();
function pinned(i){const r=readExact(i);const old=reads.get(r.path);if(old)need(old.bytes===r.bytes&&old.sha256===r.sha256,'repeated identity');reads.set(r.path,simple(r));return r;}
const current=expect4.map(n=>pinned({path:p.join(dir,n)}));
const sr=current.find(r=>p.basename(r.path)==='SOURCE_REFERENCES.json');
const S=JSON.parse(sr.body.toString('utf8'));
need(S.schema==='ri243-admitted-source-references-v1','reference schema');
need(S.status==='SOURCE_ONLY_AUTHOR_PACKET_FOR_INDEPENDENT_REVIEW','source status');
const ass=JSON.parse(pinned(S.assignment).body.toString('utf8'));
need(ass.schema==='ri243-native-hook-acquisition-assignment-v1'&&ass.reservation===dir,'assignment');
need(ass.owner_thread==='01a074c4-4b09-76a3-8cb2-0caf116f6b9c','owner');
const decision=JSON.parse(pinned(S.accepted_predecessor).body.toString('utf8'));
need(decision.status==='ACCEPT_CONDITIONAL_CANONICAL_GAP_EXCHANGE_AND_EXCEPTION_BOUNDS','accepted predecessor');
const P=JSON.parse(pinned(S.predecessor_references).body.toString('utf8'));
need(S.preserved_boundary_keys.length===15,'boundary count');
need(JSON.stringify(S.preserved_boundary_keys)===JSON.stringify(P.preserved_boundary_keys),'boundary names');
for(const k of S.preserved_boundary_keys)need(JSON.stringify(S.preserved_boundaries[k])===JSON.stringify(P.preserved_boundaries[k]),'preserved boundary '+k);
const paths=S.direct_sources.map(x=>x.identity.path);
need(new Set(paths).size===paths.length&&paths.length===81,'direct unique count');
for(const row of S.direct_sources){
need(!row.identity.path.endsWith('/CERTIFICATE.json')&&!row.identity.path.endsWith('/check.py'),'no original scientific body or executable');
need(['accepted-analytic-text','administrative-reference','opaque-historical-support'].includes(row.access),'access policy');
pinned(row.identity);
}
for(const row of P.direct_sources)need(S.direct_sources.some(x=>JSON.stringify(x.identity)===JSON.stringify(row.identity)),'inherited direct identity');
need(S.current_scope.manual_mathematical_reasoning===true,'manual reasoning');
for(const k of ['automatic_scientific_arithmetic','scientific_body_read','scientific_JSON_decoded','new_coordinate_read','original_RI41_exception_renewed','new_amplitude','H_or_z_reconstructed','subject_execution','measurement_access','RET_access','repository_changes','git_or_index_operations','successor_assigned'])need(S.current_scope[k]===false,'scope '+k);
need(S.current_scope.qualification_credit===0,'credit');
need(S.diagnostics.failed_shell_commands===0&&S.diagnostics.failed_orchestration_attempts===1&&S.diagnostics.rejected_patches===1&&S.diagnostics.clipped_displays===0,'current diagnostics');
need(JSON.stringify(S.diagnostics.predecessor_diagnostics)===JSON.stringify(P.diagnostics),'predecessor diagnostics');
need(S.proposed_acquisition.status==='DESIGN_ONLY_NOT_ISSUED_ADMISSION_NOT_EXECUTED','proposed only');
need(S.proposed_acquisition.original_source_pin_freshly_checked===false&&S.proposed_acquisition.scientific_body_displayed===false,'no current source body access');
need(S.proposed_acquisition.resolved_new_values===0&&S.proposed_acquisition.original_indices_resolved===false&&S.proposed_acquisition.default_override_status_resolved===false,'unresolved source selection');
need(JSON.stringify(S.proposed_acquisition.source_identity_from_administrative_provenance)===JSON.stringify(P.preserved_boundaries.historical_RI231_literal_exception.body),'historical body pin only');
need(!paths.includes(S.proposed_acquisition.source_identity_from_administrative_provenance.path),'body not direct read');
for(const k of ['original_RI197_RI216_RI231_exceptions_renewed','source_admission_issued','full_vector_instantiated','new_source_index_inferred'])need(S.current_scope[k]===false,'scope '+k);
const prev=JSON.parse(pinned(S.predecessor_handoff).body.toString('utf8'));
need(prev.schema==='ri240-native-canonical-order-handoff-v1','predecessor schema');
for(const i of prev.files)pinned(i);
const prevNames=fs.readdirSync(p.dirname(S.predecessor_handoff.path)).sort();
need(JSON.stringify(prevNames)===JSON.stringify(['CANONICAL_EXCHANGE.md','AUTHOR_VERIFICATION.json','HOOK_AND_EXCEPTION.md','HANDOFF.json','HANDOFF.md','SOURCE_REFERENCES.json'].sort()),'predecessor namespace');
if(mode==='final6'){
const h=JSON.parse(pinned({path:p.join(dir,'HANDOFF.json')}).body.toString('utf8'));
need(h.schema==='ri243-native-hook-acquisition-handoff-v1','handoff schema');
need(h.status==='SEALED_SOURCE_ONLY_AUTHOR_RESULT_PENDING_INDEPENDENT_REVIEW','handoff status');
need(h.reservation===dir&&h.files.length===5,'handoff reservation/files');
need(JSON.stringify(h.namespace)===JSON.stringify(expect6),'handoff namespace');
for(const i of h.files)pinned(i);
const ai=h.files.find(i=>p.basename(i.path)==='AUTHOR_VERIFICATION.json');need(ai,'author pin');
const a=JSON.parse(pinned(ai).body.toString('utf8'));
need(a.schema==='ri243-author-verification-v1','author schema');
need(a.independent_acceptance===false&&a.scientific_execution===false,'author credit');
need(JSON.stringify(a.payloads)===JSON.stringify(current.map(simple)),'four payload pins');
need(JSON.stringify(a.diagnostics)===JSON.stringify(S.diagnostics)&&JSON.stringify(h.diagnostics)===JSON.stringify(S.diagnostics),'diagnostics match');
need(h.actual_full_normalized_witness===false&&h.actual_signed_inconsistency===false,'actual branch remains open');
need(h.accepted_full_system_iff_retained===true&&h.complete_original_recovery_retained===true,'conditional result scope');
need(h.successor_assigned===false&&h.qualification_credit===0,'scope');
for(const i of current.map(simple))need(h.files.some(x=>JSON.stringify(x)===JSON.stringify(i)),'handoff pins');
}
for(const i of reads.values())readExact(i);
console.log(JSON.stringify({
schema:'ri243-metadata-check-result-v1',mode,exit_intent:0,
scope:'Metadata identities, namespace, administrative declarations and unchanged boundaries only; no scientific content parsing or proof arithmetic.',
direct_sources:S.direct_sources.length,direct_bytes:S.direct_sources.reduce((n,x)=>n+x.identity.bytes,0),
whole_identities:reads.size,preserved_boundaries:S.preserved_boundary_keys.length,
predecessor_namespace:prevNames,current_namespace:mode==='preseal'?expect4:expect6,
inherited_manifest_by_reference:S.preserved_boundaries.inherited_manifest_by_reference,
scientific_body_read:false,scientific_execution:false,proof_arithmetic:false,
current_identities:[...reads.values()].filter(x=>p.dirname(x.path)===dir),
read_identities:[...reads.values()]
}));
